   Pré-requisito: 01_ddl.sql já executado.
   Execução ....: pgAdmin/DBeaver (abrir e executar o arquivo inteiro) ou
                  psql -d <banco> -v ON_ERROR_STOP=1 -f 02_carga.sql

   Estratégia (ELT em SQL puro):
     Etapa 1 - Staging: as 887 linhas do CSV entram SEM ALTERAÇÃO numa tabela
               de texto (schema "staging"). Arquivo gerado por
               scripts/gerar_carga.py (Python só converte linha -> INSERT).
     Etapa 2 - Tabelas de referência: SELECT DISTINCT a partir do staging.
     Etapa 3 - Tabela barragem: INSERT ... SELECT com JOIN nas referências,
               conversão de tipos e diagnóstico da capacidade.
     Etapa 4 - Verificações automáticas (o script aborta se algo não bater).

   Tudo roda numa única transação: ou carrega tudo, ou nada.
   ============================================================================= */

SET client_encoding = 'UTF8';

BEGIN;

/* -----------------------------------------------------------------------------
   ETAPA 1 - STAGING (cópia fiel do CSV, todas as colunas como texto)
   ----------------------------------------------------------------------------- */
DROP SCHEMA IF EXISTS staging CASCADE;
CREATE SCHEMA staging;

CREATE TABLE staging.csv_barragens (
    cod_snisb                  TEXT NOT NULL,
