/* -----------------------------------------------------------------------------
   ETAPA 2 - TABELAS DE REFERÊNCIA
   Convenção: campo vazio no CSV ('') vira NULL (NULLIF(x, '')).
   ----------------------------------------------------------------------------- */

-- 2.1 UF: tabela de referência completa (27 UFs). Só a sigla vem do CSV;
--     o nome por extenso é dado público (IBGE) e apenas enriquece o modelo.
INSERT INTO uf (sigla, nome) VALUES
    ('AC','Acre'), ('AL','Alagoas'), ('AP','Amapá'), ('AM','Amazonas'),
    ('BA','Bahia'), ('CE','Ceará'), ('DF','Distrito Federal'),
    ('ES','Espírito Santo'), ('GO','Goiás'), ('MA','Maranhão'),
    ('MT','Mato Grosso'), ('MS','Mato Grosso do Sul'), ('MG','Minas Gerais'),
    ('PA','Pará'), ('PB','Paraíba'), ('PR','Paraná'), ('PE','Pernambuco'),
    ('PI','Piauí'), ('RJ','Rio de Janeiro'), ('RN','Rio Grande do Norte'),
    ('RS','Rio Grande do Sul'), ('RO','Rondônia'), ('RR','Roraima'),
    ('SC','Santa Catarina'), ('SP','São Paulo'), ('SE','Sergipe'),
    ('TO','Tocantins');

-- 2.2 Município. Na fonte, 5 municípios aparecem com duas grafias que só
--     diferem em maiúsculas/minúsculas (ex.: 'LONDRINA' e 'Londrina' / PR).
--     São o MESMO município: guardamos uma única linha, usando a grafia em
--     CAIXA ALTA (padrão de 98% dos registros do SNISB).
INSERT INTO municipio (nome, sigla_uf)
SELECT DISTINCT ON (upper(municipio), uf)
       municipio, uf
FROM staging.csv_barragens
ORDER BY upper(municipio), uf,
         (municipio = upper(municipio)) DESC,   -- prefere a grafia em caixa alta
         municipio;

-- 2.3 Região hidrográfica
INSERT INTO regiao_hidrografica (nome)
SELECT DISTINCT regiao_hidrografica
FROM staging.csv_barragens
ORDER BY 1;

-- 2.4 Curso d'água: chave natural (nome, região) - homônimos em regiões
--     diferentes (ex.: 'Rio Grande') são cursos d'água diferentes.
INSERT INTO curso_dagua (nome, id_regiao)
SELECT DISTINCT s.curso_dagua, r.id_regiao
FROM staging.csv_barragens s
JOIN regiao_hidrografica r ON r.nome = s.regiao_hidrografica
ORDER BY 1, 2;

-- 2.5 Comitês de bacia
INSERT INTO comite_bacia_federal (nome)
SELECT DISTINCT comite_federal
FROM staging.csv_barragens
WHERE comite_federal <> ''
ORDER BY 1;

INSERT INTO comite_bacia_estadual (nome)
SELECT DISTINCT comite_estadual
FROM staging.csv_barragens
WHERE comite_estadual <> ''
ORDER BY 1;

-- 2.6 Empreendedor, órgão fiscalizador, uso, material, fase de vida
INSERT INTO empreendedor (nome)
SELECT DISTINCT empreendedor FROM staging.csv_barragens ORDER BY 1;

INSERT INTO orgao_fiscalizador (nome)
SELECT DISTINCT orgao_fiscalizador FROM staging.csv_barragens ORDER BY 1;

INSERT INTO uso_principal (descricao)
SELECT DISTINCT uso_principal FROM staging.csv_barragens ORDER BY 1;

INSERT INTO material_construcao (descricao)
SELECT DISTINCT tipo_material FROM staging.csv_barragens
WHERE tipo_material <> ''            -- vazio = NULL; 'Sem Informação' é valor próprio
ORDER BY 1;

-- Fase de vida em ordem do ciclo de vida da barragem
INSERT INTO fase_vida (descricao)
SELECT f.descricao
FROM (SELECT DISTINCT fase_vida AS descricao
      FROM staging.csv_barragens WHERE fase_vida <> '') f
ORDER BY array_position(ARRAY['Projeto','Construção','1º enchimento','Operação','Desativada'],
                        f.descricao) NULLS LAST, f.descricao;

-- 2.7 Tratamento da capacidade do reservatório (inconsistência de unidade).
--     A unidade oficial é hm³ (milhões de m³). Referências físicas:
--       * maior reservatório do Brasil = Serra da Mesa, ~54.400 hm³
--         (no próprio CSV: 54.400 / 56.950 / 52.344,52 hm³);
--       * PCH/CGH, por definição, têm reservatório pequeno.
INSERT INTO tratamento_capacidade (cod_tratamento, descricao, fator_para_hm3) VALUES
  ('CONSISTENTE',
   'Valor plausível em hm³; usado sem alteração.', 1),
  ('CONVERTIDO_M3',
   'Valor >= 1.000.000: fisicamente impossível em hm³ (acima do maior reservatório do país). Interpretado como m³ -> divide por 1.000.000.', 0.000001),
  ('CONVERTIDO_MIL_M3',
   'Valor entre 60.000 e 1.000.000: impossível em hm³ e implausível em m³ para a usina. Interpretado como mil m³ (dam³) -> divide por 1.000.', 0.001),
  ('SUSPEITO',
   'PCH/CGH com mais de 1.000 hm³: incompatível com o porte da usina, sem regra segura de conversão. capacidade_hm3 = NULL.', NULL),
  ('ZERO',
   'Capacidade igual a 0: tratada como não informada. capacidade_hm3 = NULL.', NULL);


/* -----------------------------------------------------------------------------
   ETAPA 3 - TABELA BARRAGEM
   ----------------------------------------------------------------------------- */
INSERT INTO barragem (
    cod_snisb, id_orgao_fiscalizador, cod_fiscalizador, nome, data_cadastro,
    id_empreendedor, altura_fundacao_m, altura_terreno_m, capacidade_reservatorio,
    cod_tratamento_capacidade, id_material, id_uso_principal, id_fase_vida,
    latitude, longitude, id_municipio, id_curso_dagua, cod_trecho_curso_dagua,
    dominio_curso_dagua, id_comite_federal, id_comite_estadual,
    numero_autorizacao, data_autorizacao, regulada_pnsb, possui_pae,
    possui_plano_seguranca, possui_revisao_periodica, categoria_risco,
    dano_potencial_associado, barragem_autuada, completude_cadastro
)
SELECT
    s.cod_snisb::integer,
    o.id_orgao_fiscalizador,
    s.cod_fiscalizador::integer,
    s.nome,
    s.data_cadastro::date,
    e.id_empreendedor,
    s.altura_fundacao_m::numeric,
    NULLIF(s.altura_terreno_m, '')::numeric,
    s.capacidade_reservatorio::numeric,
    CASE
        WHEN s.capacidade_reservatorio::numeric = 0          THEN 'ZERO'
        WHEN s.capacidade_reservatorio::numeric >= 1000000   THEN 'CONVERTIDO_M3'
        WHEN s.capacidade_reservatorio::numeric >  60000     THEN 'CONVERTIDO_MIL_M3'
        WHEN s.capacidade_reservatorio::numeric >  1000
             AND s.nome ~ '^(PCH|CGH)\s'                     THEN 'SUSPEITO'
        ELSE 'CONSISTENTE'
    END,
    mc.id_material,
    up.id_uso_principal,
    fv.id_fase_vida,
    s.latitude::numeric,
    s.longitude::numeric,
    m.id_municipio,
    cd.id_curso_dagua,
    NULLIF(s.cod_trecho_curso_dagua, ''),
    NULLIF(s.dominio_curso_dagua, ''),
    cf.id_comite_federal,
    ce.id_comite_estadual,
    s.numero_autorizacao,
    NULLIF(s.data_autorizacao, '')::date,
    s.regulada_pnsb::boolean,
    NULLIF(s.possui_pae, '')::boolean,
    s.possui_plano_seguranca::boolean,
    s.possui_revisao_periodica::boolean,
    s.categoria_risco,
    s.dano_potencial_associado,
    s.barragem_autuada::boolean,
    s.completude_cadastro
FROM staging.csv_barragens s
JOIN orgao_fiscalizador  o  ON o.nome  = s.orgao_fiscalizador
JOIN empreendedor        e  ON e.nome  = s.empreendedor
JOIN uso_principal       up ON up.descricao = s.uso_principal
JOIN municipio           m  ON upper(m.nome) = upper(s.municipio) AND m.sigla_uf = s.uf
JOIN regiao_hidrografica r  ON r.nome  = s.regiao_hidrografica
JOIN curso_dagua         cd ON cd.nome = s.curso_dagua AND cd.id_regiao = r.id_regiao
LEFT JOIN material_construcao   mc ON mc.descricao = s.tipo_material
LEFT JOIN fase_vida             fv ON fv.descricao = s.fase_vida
LEFT JOIN comite_bacia_federal  cf ON cf.nome      = s.comite_federal
LEFT JOIN comite_bacia_estadual ce ON ce.nome      = s.comite_estadual
ORDER BY s.cod_snisb::integer;


/* -----------------------------------------------------------------------------
   ETAPA 4 - VERIFICAÇÕES AUTOMÁTICAS (aborta a transação se falhar)
   ----------------------------------------------------------------------------- */
DO $$
DECLARE
    v_csv      integer;
    v_barragem integer;
    v_ug_erro  integer;
BEGIN
    SELECT count(*) INTO v_csv      FROM staging.csv_barragens;
    SELECT count(*) INTO v_barragem FROM barragem;

    IF v_csv <> 887 OR v_barragem <> v_csv THEN
        RAISE EXCEPTION 'Carga incompleta: staging=%, barragem=%', v_csv, v_barragem;
    END IF;

    -- A unidade de gestão (não armazenada) deve ser reconstruída sem erro
    SELECT count(*) INTO v_ug_erro
    FROM staging.csv_barragens s
    JOIN vw_barragem v ON v.cod_snisb = s.cod_snisb::integer
    WHERE v.unidade_gestao IS DISTINCT FROM NULLIF(s.unidade_gestao, '');

    IF v_ug_erro <> 0 THEN
        RAISE EXCEPTION 'unidade_gestao não reconstruível em % linhas', v_ug_erro;
    END IF;

    RAISE NOTICE 'Carga OK: % barragens carregadas; unidade_gestao reconstruída em 100%% das linhas.', v_barragem;
END
$$;

COMMIT;

-- A tabela de staging é mantida para auditoria e para o 03_validacao.sql.
-- Para deixar o banco só com o modelo normalizado, execute depois:
--     DROP SCHEMA staging CASCADE;

-- Resumo da carga
SELECT 'uf' AS tabela, count(*) AS linhas FROM uf
UNION ALL SELECT 'municipio',             count(*) FROM municipio
UNION ALL SELECT 'regiao_hidrografica',   count(*) FROM regiao_hidrografica
UNION ALL SELECT 'curso_dagua',           count(*) FROM curso_dagua
UNION ALL SELECT 'comite_bacia_federal',  count(*) FROM comite_bacia_federal
UNION ALL SELECT 'comite_bacia_estadual', count(*) FROM comite_bacia_estadual
UNION ALL SELECT 'empreendedor',          count(*) FROM empreendedor
UNION ALL SELECT 'orgao_fiscalizador',    count(*) FROM orgao_fiscalizador
UNION ALL SELECT 'uso_principal',         count(*) FROM uso_principal
UNION ALL SELECT 'material_construcao',   count(*) FROM material_construcao
UNION ALL SELECT 'fase_vida',             count(*) FROM fase_vida
UNION ALL SELECT 'tratamento_capacidade', count(*) FROM tratamento_capacidade
UNION ALL SELECT 'barragem',              count(*) FROM barragem;
